{
  "concept": "In an Atwood machine, two masses connected by a single string share the exact same tension and acceleration magnitude, even though their weights and net forces differ.",
  "figureType": "diagram",
  "elements": [
    "ceiling and pulley mounting bracket",
    "gray grooved pulley wheel",
    "yellow string passing over the pulley, connecting the two blocks",
    "square block m1 on the left side of the pulley",
    "square block m2 on the right side of the pulley",
    "labels 'm1' and 'm2' next to the blocks in the main diagram",
    "heading 'Block 1' above the first free-body diagram",
    "heading 'Block 2' above the second free-body diagram",
    "square block m1 in the first free-body diagram",
    "square block m2 in the second free-body diagram",
    "red upward tension vector labeled 'T' on Block 1 FBD",
    "red upward tension vector labeled 'T' on Block 2 FBD",
    "red downward weight vector labeled 'w1' on Block 1 FBD",
    "red downward weight vector labeled 'w2' on Block 2 FBD",
    "acceleration vector 'a' next to Block 1 FBD (visible during motion)",
    "acceleration vector 'a' next to Block 2 FBD (visible during motion)"
  ],
  "interactions": [
    {
      "id": "massM2",
      "type": "slider",
      "label": "Mass of Block 2 (m2)",
      "range": [0.5, 2.0, 0.1],
      "default": 1.5,
      "teaches": "Changing the mass alters the downward weight vectors and the system's net acceleration, but the two upward tension vectors always remain equal to each other."
    },
    {
      "id": "systemState",
      "type": "state",
      "label": "System State",
      "states": ["held", "released", "in_motion"],
      "default": "held",
      "teaches": "Releasing the blocks shows that the unequal weights cause the heavier block to accelerate downward and the lighter block to accelerate upward at the exact same rate."
    }
  ],
  "demo_steps": [
    {
      "title": "Static forces (Held)",
      "narration": "While held in place, the downward weight w2 is greater than w1. However, because they share a single string, the upward tension T is identical for both blocks.",
      "state": { "systemState": "held", "massM2": 1.5 }
    },
    {
      "title": "System released",
      "narration": "Upon release, the imbalance in weights creates a net force. Block 2 accelerates downward while Block 1 accelerates upward. Both acceleration vectors have the same magnitude.",
      "state": { "systemState": "released", "massM2": 1.5 }
    },
    {
      "title": "Reversing the mass difference",
      "narration": "If we make m2 lighter than m1, the net force reverses direction. The acceleration changes direction and magnitude, but the two tension arrows T remain perfectly equal to each other.",
      "state": { "systemState": "released", "massM2": 0.5 }
    }
  ],
  "keyInsight": "Because the blocks are physically tied together by one continuous string, they must move together (equal acceleration) and pull on each other equally (equal tension), regardless of their individual masses.",
  "reconstructionNotes": "Layout: physical pulley diagram on the left, the two free-body diagrams (FBDs) side-by-side on the right. In the FBDs, the upward tension vectors (T) MUST be drawn identically in length at all times. The downward weight vectors (w1 and w2) should scale dynamically with the mass slider. When the system state is 'released' or 'in_motion', display vertical acceleration vectors next to the FBDs that point in opposite directions but have the same length."
}

