// @FIGURE_CODE_BEGIN
const W = 650;
const H = 450;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Definitions for arrow markers
const defs = draw.defs();
const markerRed = defs.marker(10, 7, function(add) {
  add.polygon('0,0 10,3.5 0,7').fill('#d62728');
}).ref(10, 3.5).orient('auto');

const markerGreen = defs.marker(10, 7, function(add) {
  add.polygon('0,0 10,3.5 0,7').fill('#2ca02c');
}).ref(10, 3.5).orient('auto');

// --- Helper Functions ---
function createArrow(color, labelText, labelSub) {
  let line = draw.line().stroke({ color: color, width: 2, linecap: 'round' })
    .marker('end', color === '#d62728' ? markerRed : markerGreen);
  let label = draw.text(add => {
    add.tspan(labelText).font({ style: 'italic', weight: 'bold' });
    if (labelSub) add.tspan(labelSub).font({ size: 11, weight: 'bold' }).dy(4);
  }).font({ family: 'sans-serif', size: 16 }).fill(color);
  return { line, label };
}

function addInteractivity(item, title, body) {
  if (item.line) {
    item.line.css('cursor', 'pointer');
    item.line.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
  }
  if (item.label) {
    item.label.css('cursor', 'pointer');
    item.label.on('mousemove', e => showTooltip(title, e))
              .on('mouseleave', () => hideTooltip())
              .on('click', () => showPopup(title, body));
  }
  if (item.rect) {
    item.rect.css('cursor', 'pointer');
    item.rect.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
  }
}

// --- Scene Layout ---

// Divider between physical system and abstract FBDs
draw.line(320, 20, 320, 430).stroke({ color: '#e0e0e0', width: 2, dasharray: '6 4' });

// 1. Pulley System (Left)
draw.rect(200, 20).move(80, 0).fill('#ffe4c4').stroke('#e0c2a0'); // Ceiling
draw.rect(16, 80).cx(180).y(0).fill('#d0d0d0').stroke('#a0a0a0'); // Bracket

const ropeBg = draw.path().fill('none').stroke({ color: '#b3951f', width: 4 });
const ropeFg = draw.path().fill('none').stroke({ color: '#e6c229', width: 4, dasharray: '8 4' });

// Pulley wheel
draw.circle(90).center(180, 80).fill('#b0b0b0').stroke({ color: '#777', width: 2 });
draw.circle(84).center(180, 80).fill('#c8c8c8').stroke({ color: '#999', width: 1 });
draw.circle(12).center(180, 80).fill('#444');

// Main Diagram Blocks
const b1Group = draw.group();
const b1Rect = b1Group.rect(40, 40).fill('#f4d8b6').stroke({ color: '#c09d7a', width: 2 });
const b1Text = draw.text(add => { add.tspan('m'); add.tspan('1').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' });

const b2Group = draw.group();
const b2Rect = b2Group.rect(40, 40).fill('#f4d8b6').stroke({ color: '#c09d7a', width: 2 });
const b2Text = draw.text(add => { add.tspan('m'); add.tspan('2').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' });

// 2. Free Body Diagrams (Right)
const FBD1_X = 420;
const FBD2_X = 540;
const FBD_Y = 240;

draw.text('Block 1').font({ family: 'sans-serif', size: 16, weight: 'bold' }).cx(FBD1_X).cy(40);
draw.text('Block 2').font({ family: 'sans-serif', size: 16, weight: 'bold' }).cx(FBD2_X).cy(40);

const fbdB1 = draw.rect(40, 40).fill('#f4d8b6').stroke({ color: '#c09d7a', width: 2 }).cx(FBD1_X).cy(FBD_Y);
const fbdB2 = draw.rect(40, 40).fill('#f4d8b6').stroke({ color: '#c09d7a', width: 2 }).cx(FBD2_X).cy(FBD_Y);

const fbd1Text = draw.text(add => { add.tspan('m'); add.tspan('1').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' }).cx(FBD1_X).cy(FBD_Y);
const fbd2Text = draw.text(add => { add.tspan('m'); add.tspan('2').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' }).cx(FBD2_X).cy(FBD_Y);

// Vectors
const arrT1 = createArrow('#d62728', 'T', '');
const arrW1 = createArrow('#d62728', 'w', '1');
const arrA1 = createArrow('#2ca02c', 'a', '');

const arrT2 = createArrow('#d62728', 'T', '');
const arrW2 = createArrow('#d62728', 'w', '2');
const arrA2 = createArrow('#2ca02c', 'a', '');

// Tooltips
addInteractivity(arrT1, 'Tension (T)', 'The upward tension is equal for both blocks because they share the same string.');
addInteractivity(arrT2, 'Tension (T)', 'The upward tension is equal for both blocks because they share the same string.');
addInteractivity(arrW1, 'Weight (w₁)', 'The gravitational force acting on Block 1. This remains constant.');
addInteractivity(arrW2, 'Weight (w₂)', 'The gravitational force acting on Block 2. This changes as the mass changes.');
addInteractivity(arrA1, 'Acceleration (a)', 'Because they are tied together, the magnitude of acceleration is always identical for both blocks.');
addInteractivity(arrA2, 'Acceleration (a)', 'Because they are tied together, the magnitude of acceleration is always identical for both blocks.');
addInteractivity({ rect: fbdB1, label: fbd1Text }, 'Block 1', 'The free-body diagram showing only the vertical forces directly acting on Block 1.');
addInteractivity({ rect: fbdB2, label: fbd2Text }, 'Block 2', 'The free-body diagram showing only the vertical forces directly acting on Block 2.');

// --- State & Animation ---
let m1_val = 1.0;
let m2_val = 1.5;
let currentState = 'held';
let animTime = 0;
let lastTime = performance.now();
let animId = null;

function setVector(arrow, x1, y1, x2, y2, pos) {
  if (Math.abs(x2 - x1) < 0.1 && Math.abs(y2 - y1) < 0.1) {
    arrow.line.hide();
    arrow.label.hide();
    return;
  }
  arrow.line.show().plot(x1, y1, x2, y2);
  arrow.label.show();

  if (pos === 'left') {
    let isUp = y2 < y1;
    arrow.label.cx(x2 - 18).cy(y2 + (isUp ? 12 : -12));
  } else if (pos === 'left_mid') {
    arrow.label.cx((x1 + x2) / 2 - 16).cy((y1 + y2) / 2);
  } else if (pos === 'right_mid') {
    arrow.label.cx((x1 + x2) / 2 + 16).cy((y1 + y2) / 2);
  }
}

function drawScene() {
  let g_scale = 50;
  let a_val = (m2_val - m1_val) / (m1_val + m2_val); 
  let disp = 0;

  // Continuous looping animation logic
  if (currentState === 'released' && Math.abs(a_val) > 0.005) {
    let moveTime = Math.sqrt(90 / (0.5 * Math.abs(a_val) * 270));
    let cycleTime = moveTime + 0.5; // Include a 0.5s pause at the bottom
    let activeT = animTime % cycleTime;

    if (activeT > moveTime) activeT = moveTime; // Hold for the pause
    disp = 0.5 * a_val * 270 * activeT * activeT;
  }

  let y1 = 260 - disp; 
  let y2 = 260 + disp;

  let size1 = 36 + 8 * m1_val;
  let size2 = 36 + 8 * m2_val;

  // Ropes (path matching string over the pulley)
  let pathStr = `M 135 ${y1 - size1/2} L 135 80 A 45 45 0 0 1 225 80 L 225 ${y2 - size2/2}`;
  ropeBg.plot(pathStr);
  ropeFg.plot(pathStr);

  // Main diagram blocks
  b1Group.move(135 - size1/2, y1 - size1/2);
  b1Rect.size(size1, size1);
  b1Text.cx(135 - size1/2 - 20).cy(y1);

  b2Group.move(225 - size2/2, y2 - size2/2);
  b2Rect.size(size2, size2);
  b2Text.cx(225 + size2/2 + 20).cy(y2);

  // FBD logic
  fbdB1.size(size1, size1).cx(FBD1_X).cy(FBD_Y);
  fbdB2.size(size2, size2).cx(FBD2_X).cy(FBD_Y);

  let T_len = ((2 * m1_val * m2_val) / (m1_val + m2_val)) * g_scale;
  let W1_len = m1_val * g_scale;
  let W2_len = m2_val * g_scale;

  // Upward Tension T
  setVector(arrT1, FBD1_X, FBD_Y - size1/2, FBD1_X, FBD_Y - size1/2 - T_len, 'left');
  setVector(arrT2, FBD2_X, FBD_Y - size2/2, FBD2_X, FBD_Y - size2/2 - T_len, 'left');

  // Downward Weight W
  setVector(arrW1, FBD1_X, FBD_Y + size1/2, FBD1_X, FBD_Y + size1/2 + W1_len, 'left');
  setVector(arrW2, FBD2_X, FBD_Y + size2/2, FBD2_X, FBD_Y + size2/2 + W2_len, 'left');

  // Acceleration
  if (currentState === 'released' && Math.abs(a_val) > 0.005) {
    let A_len = 30 + Math.abs(a_val) * 120;
    if (a_val > 0) { // m1 up, m2 down
      setVector(arrA1, FBD1_X - 45, FBD_Y + A_len/2, FBD1_X - 45, FBD_Y - A_len/2, 'left_mid');
      setVector(arrA2, FBD2_X + 45, FBD_Y - A_len/2, FBD2_X + 45, FBD_Y + A_len/2, 'right_mid');
    } else { // m1 down, m2 up
      setVector(arrA1, FBD1_X - 45, FBD_Y - A_len/2, FBD1_X - 45, FBD_Y + A_len/2, 'left_mid');
      setVector(arrA2, FBD2_X + 45, FBD_Y + A_len/2, FBD2_X + 45, FBD_Y - A_len/2, 'right_mid');
    }
  } else {
    arrA1.line.hide(); arrA1.label.hide();
    arrA2.line.hide(); arrA2.label.hide();
  }
}

function tick(time) {
  let dt = (time - lastTime) / 1000;
  lastTime = time;
  if (currentState === 'released') {
    animTime += dt;
  }
  drawScene();
  animId = requestAnimationFrame(tick);
}

// --- Controller Interface ---
window.update_massM2 = function(val) {
  m2_val = val;
  if (currentState === 'held') { animTime = 0; }
  // (If released, changing mass midway smoothly updates forces and shifts the animation period natively)
};

window.setSystemState = function(state) {
  currentState = state;
  document.getElementById('btnHeld').classList.toggle('active', state === 'held');
  document.getElementById('btnReleased').classList.toggle('active', state !== 'held');
  animTime = 0; 
  lastTime = performance.now();
  drawScene();
};

// --- Step Player ---
const demoSteps = [
  { state: { systemState: "held", massM2: 1.5 }, narration: "While held in place, the downward weight w2 is greater than w1. However, because they share a single string, the upward tension T is identical for both blocks." },
  { state: { systemState: "released", massM2: 1.5 }, narration: "Upon release, the imbalance in weights creates a net force. Block 2 accelerates downward while Block 1 accelerates upward. Both acceleration vectors have the same magnitude." },
  { state: { systemState: "released", massM2: 0.5 }, narration: "If we make m2 lighter than m1, the net force reverses direction. The acceleration changes direction and magnitude, but the two tension arrows T remain perfectly equal to each other." }
];

let currentStep = 0;

window.nextStep = function() {
  if (currentStep < demoSteps.length - 1) applyStep(currentStep + 1);
};
window.prevStep = function() {
  if (currentStep > 0) applyStep(currentStep - 1);
};

function applyStep(idx) {
  currentStep = idx;
  const step = demoSteps[idx];

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = `Step ${idx + 1} of ${demoSteps.length}`;

  document.getElementById('massM2Input').value = step.state.massM2;
  document.getElementById('massM2Val').value = step.state.massM2;
  window.update_massM2(step.state.massM2);

  window.setSystemState(step.state.systemState);
}

// Init
setTimeout(() => {
  applyStep(0);
  requestAnimationFrame(tick);
  window.__markRendered();
}, 0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

