    labelGroup.line(-4, -16, 4, -16).stroke({ color: color, width: 1.5, linecap: 'round' })
      .marker('end', color === '#d62728' ? markerHatRed : markerHatGreen);
  }

  return { line, labelGroup, txt };
}

function setVector(arrow, x1, y1, x2, y2, pos) {
  if (Math.abs(x2 - x1) < 0.1 && Math.abs(y2 - y1) < 0.1) {
    arrow.line.hide();
    arrow.labelGroup.hide();
    return;
  }
  arrow.line.show().plot(x1, y1, x2, y2);
  arrow.labelGroup.show();

  let labelX = 0;
  let labelY = 0;

  if (pos === 'left') {
    let isUp = y2 < y1;
    labelX = x2 - 20;
    labelY = y2 + (isUp ? 22 : -8);
  } else if (pos === 'left_mid') {
    labelX = (x1 + x2) / 2 - 20;
    labelY = (y1 + y2) / 2 + 5;
  } else if (pos === 'right_mid') {
    labelX = (x1 + x2) / 2 + 20;
    labelY = (y1 + y2) / 2 + 5;
  }

  arrow.labelGroup.attr('transform', `translate(${labelX},${labelY})`);
}

function addInteractivity(item, title, body) {
  if (item.line) {
    item.line.css('cursor', 'pointer');
    item.line.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
  }
  if (item.labelGroup) {
    item.labelGroup.css('cursor', 'pointer');
    item.labelGroup.on('mousemove', e => showTooltip(title, e))
                   .on('mouseleave', () => hideTooltip())
                   .on('click', () => showPopup(title, body));
  }
  if (item.rect) {
    item.rect.css('cursor', 'pointer');
    item.rect.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
