const W = 650;
const H = 450;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Definitions for arrow markers
const defs = draw.defs();
const markerRed = defs.marker(10, 7, function(add) {
  add.polygon('0,0 10,3.5 0,7').fill('#d62728');
}).ref(10, 3.5).orient('auto');

const markerGreen = defs.marker(10, 7, function(add) {
  add.polygon('0,0 10,3.5 0,7').fill('#2ca02c');
}).ref(10, 3.5).orient('auto');

const markerHatRed = defs.marker(6, 4, function(add) {
  add.polygon('0,0 6,2 0,4').fill('#d62728');
}).ref(5, 2).orient('auto');

const markerHatGreen = defs.marker(6, 4, function(add) {
  add.polygon('0,0 6,2 0,4').fill('#2ca02c');
}).ref(5, 2).orient('auto');

// --- Helper Functions ---
function createArrow(color, mainTxt, subTxt, hasHat) {
  let line = draw.line().stroke({ color: color, width: 2, linecap: 'round' })
    .marker('end', color === '#d62728' ? markerRed : markerGreen);

  let labelGroup = draw.group();

  let txt = labelGroup.text(add => {
    add.tspan(mainTxt).font({ style: 'italic', weight: 'bold' });
    if (subTxt) {
      add.tspan(subTxt).font({ size: 11, weight: 'bold', style: 'normal' }).dy(4);
    }
  }).font({ family: 'sans-serif', size: 16 }).fill(color);

  txt.attr({ 'text-anchor': 'middle' }); 

  if (hasHat) {
    labelGroup.line(-4, -16, 4, -16).stroke({ color: color, width: 1.5, linecap: 'round' })
      .marker('end', color === '#d62728' ? markerHatRed : markerHatGreen);
  }

  return { line, labelGroup, txt };
}

function setVector(arrow, x1, y1, x2, y2, pos) {
  if (Math.abs(x2 - x1) < 0.1 && Math.abs(y2 - y1) < 0.1) {
    arrow.line.hide();
    arrow.labelGroup.hide();
    return;
  }
  arrow.line.show().plot(x1, y1, x2, y2);
  arrow.labelGroup.show();

  let labelX = 0;
  let labelY = 0;

  if (pos === 'left') {
    let isUp = y2 < y1;
    labelX = x2 - 20;
    labelY = y2 + (isUp ? 22 : -8);
  } else if (pos === 'left_mid') {
    labelX = (x1 + x2) / 2 - 20;
    labelY = (y1 + y2) / 2 + 5;
  } else if (pos === 'right_mid') {
    labelX = (x1 + x2) / 2 + 20;
    labelY = (y1 + y2) / 2 + 5;
  }

  arrow.labelGroup.attr('transform', `translate(${labelX},${labelY})`);
}

function addInteractivity(item, title, body) {
  if (item.line) {
    item.line.css('cursor', 'pointer');
    item.line.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
  }
  if (item.labelGroup) {
    item.labelGroup.css('cursor', 'pointer');
    item.labelGroup.on('mousemove', e => showTooltip(title, e))
                   .on('mouseleave', () => hideTooltip())
                   .on('click', () => showPopup(title, body));
  }
  if (item.rect) {
    item.rect.css('cursor', 'pointer');
    item.rect.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
  }
}

