Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div id="demoPlayer" style="margin-bottom: 12px; border-bottom: 1px solid #dcdfe3; padding-bottom: 12px;">
  <p id="demoNarration" style="margin: 0; font-size: 11px; line-height: 1.4; color: #222; min-height: 60px; max-width: 180px;"></p>
  <div style="display: flex; gap: 8px; justify-content: center; align-items: center; margin-top: 8px;">
    <button onclick="prevStep()" style="padding: 4px 10px; font-size: 11px;">◀ Prev</button>
    <span id="stepLabel" style="font-weight: 600; font-size: 11px;"></span>
    <button onclick="nextStep()" style="padding: 4px 10px; font-size: 11px;">Next ▶</button>
  </div>
</div>

<label style="font-weight: 600; margin-bottom: 8px;">
  Mass of Block 2 (m₂): <output id="massM2Val" style="font-weight: normal;">1.5</output>
  <input id="massM2Input" type="range" min="0.5" max="2.0" step="0.1" value="1.5" 
         oninput="document.getElementById('massM2Val').value=this.value; update_massM2(+this.value)"
         style="margin-top: 4px;">
</label>

<div style="margin-top: 16px;">
  <span style="display: block; margin-bottom: 6px; font-weight: 600;">System State:</span>
  <div style="display: flex; gap: 6px;">
    <button id="btnRelease" onclick="setSystemState('t=0_release')" class="active" style="flex: 1; padding: 6px;">t=0 (Release)</button>
    <button id="btnMotion" onclick="setSystemState('in_motion')" style="flex: 1; padding: 6px;">In Motion</button>
  </div>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
const W = 650;
const H = 450;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Definitions for arrow markers
const defs = draw.defs();
const markerRed = defs.marker(10, 7, function(add) {
  add.polygon('0,0 10,3.5 0,7').fill('#d62728');
}).ref(9, 3.5).orient('auto');

// --- Helper Functions ---
function createArrow(color, mainTxt, subTxt) {
  let line = draw.line().stroke({ color: color, width: 2.5, linecap: 'round' })
    .marker('end', markerRed);

  let labelGroup = draw.group();

  let txt = labelGroup.text(add => {
    add.tspan(mainTxt + '\u20D7').font({ style: 'italic', weight: 'bold' });
    if (subTxt) {
      add.tspan(subTxt).font({ size: 12, weight: 'bold', style: 'normal' }).dy(5);
    }
  }).font({ family: 'sans-serif', size: 18 }).fill('#000');

  txt.attr({ 'text-anchor': 'middle' }); 

  return { line, labelGroup, txt };
}

function setVector(arrow, x1, y1, x2, y2, pos) {
  if (Math.abs(x2 - x1) < 0.1 && Math.abs(y2 - y1) < 0.1) {
    arrow.line.hide();
    arrow.labelGroup.hide();
    return;
  }
  arrow.line.show().plot(x1, y1, x2, y2);
  arrow.labelGroup.show();

  let labelX = 0;
  let labelY = 0;

  if (pos === 'left') {
    let isUp = y2 < y1;
    labelX = x2 - 22;
    labelY = y2 + (isUp ? 18 : -14);
  }

  arrow.labelGroup.attr('transform', `translate(${labelX},${labelY})`);
}

function addInteractivity(item, title, body) {
  if (item.line) {
    item.line.css('cursor', 'pointer');
    item.line.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
  }
  if (item.labelGroup) {
    item.labelGroup.css('cursor', 'pointer');
    item.labelGroup.on('mousemove', e => showTooltip(title, e))
                   .on('mouseleave', () => hideTooltip())
                   .on('click', () => showPopup(title, body));
  }
  if (item.rect) {
    item.rect.css('cursor', 'pointer');
    item.rect.on('mousemove', e => showTooltip(title, e))
             .on('mouseleave', () => hideTooltip())
             .on('click', () => showPopup(title, body));
  }
}

// --- Scene Layout ---

// 1. Pulley System (Left)
// Ceiling
draw.rect(200, 20).move(80, 0).fill('#ffe4c4').stroke({ color: '#d0b090', width: 1 }); 
// Bracket Plate
draw.rect(100, 8).center(180, 24).fill('#e0e0e0').stroke({color: '#a0a0a0', width: 1});
// Bracket Bolts
draw.circle(10).center(145, 24).fill('#f0f0f0').stroke({color: '#999', width: 1});
draw.circle(10).center(215, 24).fill('#f0f0f0').stroke({color: '#999', width: 1});
// Curved Bracket
draw.path('M 174 28 L 174 65 Q 174 80 168 80 L 168 85 L 192 85 L 192 80 Q 186 80 186 65 L 186 28 Z')
    .fill('#d0d0d0').stroke({color: '#a0a0a0', width: 1, linejoin: 'round'});

const ropeBg = draw.path().fill('none').stroke({ color: '#b3951f', width: 4 });
const ropeFg = draw.path().fill('none').stroke({ color: '#e6c229', width: 4, dasharray: '8 4' });

// Pulley wheel
draw.circle(90).center(180, 80).fill('#a0a0a0').stroke({ color: '#777', width: 2 });
draw.circle(84).center(180, 80).fill('#c0c0c0').stroke({ color: '#999', width: 1 });
draw.circle(12).center(180, 80).fill('#444');

// Main Diagram Blocks
const b1Group = draw.group();
const b1Rect = b1Group.rect(45, 45).fill('#f4d8b6').stroke({ color: '#a0a0a0', width: 2 });
const b1Text = draw.text(add => { add.tspan('m').font({ style: 'italic' }); add.tspan('1').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' }).attr({ 'text-anchor': 'middle' }).fill('#000');

const b2Group = draw.group();
const b2Rect = b2Group.rect(45, 45).fill('#f4d8b6').stroke({ color: '#a0a0a0', width: 2 });
const b2Text = draw.text(add => { add.tspan('m').font({ style: 'italic' }); add.tspan('2').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' }).attr({ 'text-anchor': 'middle' }).fill('#000');

// 2. Free Body Diagrams (Right)
const FBD1_X = 420;
const FBD2_X = 540;
const FBD_Y = 240;

draw.text('Block 1').font({ family: 'sans-serif', size: 16, weight: 'bold' }).cx(FBD1_X).cy(40);
draw.text('Block 2').font({ family: 'sans-serif', size: 16, weight: 'bold' }).cx(FBD2_X).cy(40);

const fbdB1 = draw.rect(45, 45).fill('#f4d8b6').stroke({ color: '#a0a0a0', width: 2 });
const fbdB2 = draw.rect(45, 45).fill('#f4d8b6').stroke({ color: '#a0a0a0', width: 2 });

const fbd1Text = draw.text(add => { add.tspan('m').font({ style: 'italic' }); add.tspan('1').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' }).attr({ 'text-anchor': 'middle' }).fill('#000');
const fbd2Text = draw.text(add => { add.tspan('m').font({ style: 'italic' }); add.tspan('2').font({ size: 11 }).dy(4); })
  .font({ family: 'sans-serif', size: 16, weight: 'bold' }).attr({ 'text-anchor': 'middle' }).fill('#000');

// Vectors
const arrT1 = createArrow('#d62728', 'T', '');
const arrW1 = createArrow('#d62728', 'w', '1');

const arrT2 = createArrow('#d62728', 'T', '');
const arrW2 = createArrow('#d62728', 'w', '2');

// Tooltips
addInteractivity(arrT1, 'Tension (T)', 'The upward tension is identically equal for both blocks because they share the same continuous string.');
addInteractivity(arrT2, 'Tension (T)', 'The upward tension is identically equal for both blocks because they share the same continuous string.');
addInteractivity(arrW1, 'Weight (w₁)', 'The downward gravitational force acting on Block 1. This remains constant here.');
addInteractivity(arrW2, 'Weight (w₂)', 'The downward gravitational force acting on Block 2. This changes as mass m₂ changes.');
addInteractivity({ rect: fbdB1 }, 'Block 1', 'The free-body diagram mapping vertical forces acting on Block 1.');
addInteractivity({ rect: fbdB2 }, 'Block 2', 'The free-body diagram mapping vertical forces acting on Block 2.');

// --- State & Animation ---
let m1_val = 1.0;
let m2_val = 1.5;
let currentState = 't=0_release';
let animTime = 0;
let lastTime = performance.now();
let animId = null;

function drawScene() {
  let g_scale = 55;
  let a_val = (m2_val - m1_val) / (m1_val + m2_val); 
  let disp = 0;

  if (currentState === 'in_motion' && Math.abs(a_val) > 0.005) {
    let moveTime = Math.sqrt(90 / (0.5 * Math.abs(a_val) * 270));
    let cycleTime = moveTime + 0.5; // Hold at the end
    let activeT = animTime % cycleTime;

    if (activeT > moveTime) activeT = moveTime; 
    disp = 0.5 * a_val * 270 * activeT * activeT;
  }

  let y1 = 260 - disp; 
  let y2 = 260 + disp;

  let sizeW = 45;
  let size1H = 45 * m1_val;
  let size2H = 45 * m2_val;

  // Ropes
  let pathStr = `M 135 ${y1 - size1H/2} L 135 80 A 45 45 0 0 1 225 80 L 225 ${y2 - size2H/2}`;
  ropeBg.plot(pathStr);
  ropeFg.plot(pathStr);

  // Main diagram blocks
  b1Group.move(135 - sizeW/2, y1 - size1H/2);
  b1Rect.size(sizeW, size1H);
  b1Text.cx(135 - sizeW/2 - 22).cy(y1);

  b2Group.move(225 - sizeW/2, y2 - size2H/2);
  b2Rect.size(sizeW, size2H);
  b2Text.cx(225 - sizeW/2 - 22).cy(y2);

  // FBD logic
  fbdB1.size(sizeW, size1H).cx(FBD1_X).cy(FBD_Y);
  fbdB2.size(sizeW, size2H).cx(FBD2_X).cy(FBD_Y);

  fbd1Text.cx(FBD1_X - sizeW/2 - 22).cy(FBD_Y);
  fbd2Text.cx(FBD2_X - sizeW/2 - 22).cy(FBD_Y);

  let T_len = ((2 * m1_val * m2_val) / (m1_val + m2_val)) * g_scale;
  let W1_len = m1_val * g_scale;
  let W2_len = m2_val * g_scale;

  // Upward Tension T
  setVector(arrT1, FBD1_X, FBD_Y - size1H/2, FBD1_X, FBD_Y - size1H/2 - T_len, 'left');
  setVector(arrT2, FBD2_X, FBD_Y - size2H/2, FBD2_X, FBD_Y - size2H/2 - T_len, 'left');

  // Downward Weight W
  setVector(arrW1, FBD1_X, FBD_Y + size1H/2, FBD1_X, FBD_Y + size1H/2 + W1_len, 'left');
  setVector(arrW2, FBD2_X, FBD_Y + size2H/2, FBD2_X, FBD_Y + size2H/2 + W2_len, 'left');
}

function tick(time) {
  let dt = (time - lastTime) / 1000;
  lastTime = time;
  if (currentState === 'in_motion') {
    animTime += dt;
  }
  drawScene();
  animId = requestAnimationFrame(tick);
}

// --- Controller Interface ---
window.update_massM2 = function(val) {
  m2_val = val;
  if (currentState === 't=0_release') { animTime = 0; }
  drawScene();
};

window.setSystemState = function(state) {
  currentState = state;
  document.getElementById('btnRelease').classList.toggle('active', state === 't=0_release');
  document.getElementById('btnMotion').classList.toggle('active', state === 'in_motion');
  animTime = 0; 
  lastTime = performance.now();
  drawScene();
};

// --- Step Player ---
const demoSteps = [
  { state: { systemState: "t=0_release", massM2: 1.5 }, narration: "Initial logic and parameters are validated. At exactly t=0 of release, unequal weights instantly establish a net force while upward tension T remains perfectly equal." },
  { state: { systemState: "in_motion", massM2: 0.5 }, narration: "Standard processing applied. Adjusting m2 reverses the acceleration direction directly without altering the fundamental equality of the tension vectors." }
];

let currentStep = 0;

window.nextStep = function() {
  if (currentStep < demoSteps.length - 1) applyStep(currentStep + 1);
};
window.prevStep = function() {
  if (currentStep > 0) applyStep(currentStep - 1);
};

function applyStep(idx) {
  currentStep = idx;
  const step = demoSteps[idx];

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = `Step ${idx + 1} of ${demoSteps.length}`;

  document.getElementById('massM2Input').value = step.state.massM2;
  document.getElementById('massM2Val').value = step.state.massM2;
  window.update_massM2(step.state.massM2);
  window.setSystemState(step.state.systemState);
}

// Init
setTimeout(() => {
  applyStep(0);
  requestAnimationFrame(tick);
  window.__markRendered();
}, 0);
// @FIGURE_CODE_END

